namespace {
struct ModalStep{const wchar_t* title;int answer;bool task{};};
struct Modals {
    std::thread thread;std::atomic<bool> done{};unsigned found{};std::string failure;
    void start(const Product& product,std::vector<ModalStep> steps){thread=std::thread([&,steps]{for(const auto& step:steps){const auto end=GetTickCount64()+20000;HWND h{};while(!done&&!h&&GetTickCount64()<end){h=process_window(product.pid,L"#32770");if(h&&(!IsWindowVisible(h)||foreign_text(h)!=step.title))h=nullptr;if(!h)Sleep(10);}if(!h){failure="expected owned shipping modal missing";return;}++found;PostMessageW(h,step.task?TDM_CLICK_BUTTON:WM_COMMAND,step.answer,0);while(!done&&IsWindow(h)&&GetTickCount64()<end)Sleep(10);}});}
    void finish(unsigned expected){done=true;if(thread.joinable())thread.join();if(!failure.empty()||found!=expected)std::cerr<<"Modal diagnostics found="<<found<<" expected="<<expected<<" failure="<<failure<<'\n';check(failure.empty()&&found==expected,"all expected shipping review/navigation dialogs handled");}
    ~Modals(){done=true;if(thread.joinable())thread.join();}
};
void item_check(Product& process,HWND list,int row,bool selected){LVITEMW item{};item.state=INDEXTOSTATEIMAGEMASK(selected?2:1);item.stateMask=LVIS_STATEIMAGEMASK;void* remote=VirtualAllocEx(process.process.get(),nullptr,sizeof(item),MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE);check(remote!=nullptr,"owned list state buffer");SIZE_T size{};check(WriteProcessMemory(process.process.get(),remote,&item,sizeof(item),&size)&&size==sizeof(item),"list state copied into owned process");const auto ok=SendMessageW(list,LVM_SETITEMSTATE,row,reinterpret_cast<LPARAM>(remote));VirtualFreeEx(process.process.get(),remote,0,MEM_RELEASE);check(ok!=0,"actual checkbox state changed");}
void choose(HWND combo,const std::wstring& text){const auto count=SendMessageW(combo,CB_GETCOUNT,0,0);for(int i=0;i<count;++i){wchar_t value[256]{};SendMessageW(combo,CB_GETLBTEXT,i,reinterpret_cast<LPARAM>(value));if(text==value){SendMessageW(combo,CB_SETCURSEL,i,0);SendMessageW(GetParent(GetParent(combo)),WM_COMMAND,MAKEWPARAM(GetDlgCtrlID(combo),CBN_SELCHANGE),reinterpret_cast<LPARAM>(combo));return;}}throw std::runtime_error("named combo entry missing");}
}
int main(int argc,char** argv){Product config,panel,manager;try{
    check(argc==3,"fresh evidence and closed baseline/offline/online mode");const std::string mode=argv[2];check(mode=="--baseline"||mode=="--offline"||mode=="--online","closed test mode");const bool baseline=mode=="--baseline",online=mode=="--online";
    const auto out=std::filesystem::absolute(argv[1]);check(!std::filesystem::exists(out),"retain all earlier shipping evidence");std::filesystem::create_directories(out);const auto root=win32::installation::canonical_root(network_setup_qualification_root());const auto owner=win32::installation::operator_sid();check(!win32::installation::elevated(),"ordinary shipping owner");win32::installation::verify_runtime_installation(root,owner);
    const auto original=win32::offline_ftn_configuration(root,owner);check(original&&original.value&&original.value->networks.size()==2,"saved two-network fixture");const auto before_echoes=original.value->message_echoes.size();auto tag_prefix=out.filename().string()+".";for(auto& letter:tag_prefix)if(letter>='a'&&letter<='z')letter=static_cast<char>(letter-'a'+'A');const auto source=out/L"fido.na";{std::ofstream stream(source);for(int i=1;i<=6;++i)stream<<tag_prefix<<i<<" Echo description "<<i<<'\n';}
    if(online){panel=launch(root/L"Bin/SFXControlPanel.exe",L"");panel.window=wait_window(panel.pid,kWindowClass);const auto until=GetTickCount64()+30000;while(!visible_text_contains(panel.window,L"READY")&&GetTickCount64()<until)Sleep(10);check(visible_text_contains(panel.window,L"READY"),"actual Runtime ready");}
    config=launch(root/L"Bin/SFXConfig.exe",L"--ftn");config.window=wait_window(config.pid,L"SFXConfigWindow");
    const auto control=[&](int id){HWND h{};const auto until=GetTickCount64()+20000;while(!h&&GetTickCount64()<until){h=visible_control(config.window,id);if(!h)Sleep(10);}check(h!=nullptr,("shipping control "+std::to_string(id)).c_str());return h;};
    const auto click=[&](int id){DWORD_PTR result{};check(SendMessageTimeoutW(control(id),BM_CLICK,0,0,SMTO_ABORTIFHUNG,30000,&result)!=0,"shipping command responds");};
    const auto set=[&](int id,const std::wstring& text){check(set_foreign_text(control(id),text.c_str()),"shipping edit value");};
    const auto close=[&]{PostMessageW(config.window,WM_CLOSE,0,0);check(WaitForSingleObject(config.process.get(),20000)==WAIT_OBJECT_0,"Config closes without unsaved loop");config.window=nullptr;close_panel(panel);};
    control(IDC_FTN_LIST);SendMessageW(control(IDC_FTN_LIST),LB_SETCURSEL,0,0);click(IDC_FTN_EDIT);control(IDC_FTN_NAME);check(foreign_text(control(IDC_FTN_NAME))==L"FidoNet","selected network is FidoNet");click(IDC_FTN_ECHOES);click(IDC_FTN_ECHO_IMPORT);control(IDC_FTN_IMPORT_PATH);SendMessageW(control(IDC_FTN_IMPORT_SOURCE),CB_SETCURSEL,1,0);set(IDC_FTN_IMPORT_PATH,source.native());click(IDC_FTN_IMPORT_LOAD);check(SendMessageW(control(IDC_FTN_IMPORT_ROWS),LVM_GETITEMCOUNT,0,0)==6,"six actual loaded echo rows");
    const auto apply=[&]{std::cout<<"APPLY shipping review\n"<<std::flush;Modals dialogs;dialogs.start(config,{{L"Review Selected Echo Import",IDOK,false}});click(IDC_FTN_IMPORT_APPLY);if(!dialogs.found)render_foreign_png(config.window,out/L"apply-without-review.png");dialogs.finish(1);};
    if(baseline){
        SendMessageW(control(IDC_FTN_IMPORT_GROUP),CB_SETCURSEL,0,0);apply();check(visible_text_contains(config.window,L"changed elsewhere"),"actual R13 duplicate group save refused");choose(control(IDC_FTN_IMPORT_GROUP),L"FidoNet");apply();check(visible_text_contains(config.window,L"changed elsewhere")&&visible_control(config.window,IDC_FTN_IMPORT_APPLY),"actual R13 corrected-group retry remains refused");render_foreign_png(config.window,out/L"r13-retained-import-conflict.png");click(IDC_FTN_IMPORT_BACK);close();const auto after=win32::offline_ftn_configuration(root,owner);check(after&&after.value&&app::encode_ftn_configuration(*after.value)==app::encode_ftn_configuration(*original.value),"failed baseline/discard leaves all saved configuration exact");
    }else{
        wchar_t cls[32]{};GetClassNameW(control(IDC_FTN_IMPORT_GROUP),cls,32);check(std::wstring(cls)==L"Static"&&!visible_control(config.window,IDC_FTN_IMPORT_NEW_GROUP)&&foreign_text(control(IDC_FTN_IMPORT_GROUP)).find(L"Message group: FidoNet")!=std::wstring::npos,"automatic read-only FidoNet destination, both old editors removed");
        if(!online){
            const auto catalog=win32::offline_message_configuration_snapshot(root,owner,{});check(catalog.code==app::LocalAccountResultCode::ok,"actual concurrent catalog snapshot");app::MessageConfigurationChange change;check(win32::fill_secure_random(change.operation.bytes.data(),change.operation.bytes.size()),"unique concurrent owner operation");change.action=app::MessageConfigurationAction::group;change.expected_configuration_revision=catalog.catalog.revision;change.group.name="Concurrent "+out.filename().string();change.group.access=10;check(win32::offline_change_message_configuration(root,owner,change).code==app::LocalAccountResultCode::ok,"independent real owner writer advances catalog revision");
            apply();check(visible_text_contains(config.window,L"Reload Saved Settings")&&visible_control(config.window,IDC_FTN_IMPORT_APPLY),"actual stale-catalog save fails with recovery action");const auto unchanged=win32::offline_ftn_configuration(root,owner);check(unchanged&&unchanged.value&&unchanged.value->message_echoes.size()==before_echoes,"failed import created no partial echo");
        }
        set(IDC_FTN_IMPORT_ACCESS,L"10");set(IDC_FTN_IMPORT_READ,L"20");set(IDC_FTN_IMPORT_POST,L"30");click(IDC_FTN_IMPORT_REQUIREMENTS);item_check(config,control(IDC_FTN_IMPORT_ROWS),5,false);
        if(!online){click(IDC_FTN_IMPORT_RELOAD);check(visible_text_contains(config.window,L"requirements kept"),"explicit shipping reload preserves selected entries and requirements");}
        {Modals cancel;cancel.start(config,{{L"Spitfire-X BBS Configuration",103,true}});click(IDC_FTN_IMPORT_BACK);cancel.finish(1);check(visible_control(config.window,IDC_FTN_IMPORT_APPLY)!=nullptr,"Cancel Navigation retains actual import editor");}
        render_foreign_png(config.window,out/L"review-before-save.png");
        {Modals save;save.start(config,{{L"Spitfire-X BBS Configuration",101,true},{L"Review Selected Echo Import",IDOK,false}});click(IDC_FTN_IMPORT_BACK);save.finish(2);control(IDC_FTN_NAME);check(foreign_text(control(IDC_FTN_NAME))==L"FidoNet"&&!process_window(config.pid,L"#32770"),"Save and Continue completes review and requested network navigation");}
        click(IDC_FTN_ECHOES);check(SendMessageW(control(IDC_FTN_ECHO_LIST),LB_GETCOUNT,0,0)==static_cast<LRESULT>(before_echoes+5),"only five selected echoes saved, no duplicate staged rows");render_foreign_png(config.window,out/L"saved-echoes.png");close();
        const auto after=win32::offline_ftn_configuration(root,owner);check(after&&after.value&&after.value->message_echoes.size()==before_echoes+5&&after.value->networks[0].message_group>0&&!after.value->networks[1].message_group,"saved FidoNet binding and separate unchanged X-League");unsigned added{};for(const auto& e:after.value->message_echoes)if(e.tag.rfind(tag_prefix,0)==0){++added;check(e.local_echo>0&&e.network=="FIDO"&&e.access_level==10&&e.read_level==20&&e.post_level==30&&e.maximum_messages==500U&&!e.maximum_age_days&&!e.pipe_colors&&e.ansi_colors==false&&e.require_real_name,"saved selected echo names/levels/defaults match reviewed controls");}check(added==5,"exact five intended tags");
        {sfx::adapters::storage::internal::SqliteConnection db(root/L"Data/SFX.DB",SQLITE_OPEN_READONLY,std::chrono::milliseconds(100),false);check(db.scalar_int64("SELECT count(*) FROM sfx_message_groups WHERE name='FidoNet'","one existing group")==1,"no duplicate FidoNet group");check(db.scalar_int64("SELECT count(*) FROM sfx_ftn_provider_requests","import never subscribes")==0,"no implicit AreaFix request");check(db.scalar_int64("PRAGMA user_version","schema stable")==25,"schema25 unchanged");}
        config=launch(root/L"Bin/SFXConfig.exe",L"--ftn");config.window=wait_window(config.pid,L"SFXConfigWindow");control(IDC_FTN_LIST);close();const auto reopened=win32::offline_ftn_configuration(root,owner);check(reopened&&reopened.value&&app::encode_ftn_configuration(*reopened.value)==app::encode_ftn_configuration(*after.value),"normal reopen does not change saved import");
        manager=launch(root/L"Bin/SFXFileManager.exe",L"");manager.window=wait_window(manager.pid,L"SFXFileManagerWindow");render_foreign_png(manager.window,out/L"file-manager-shared-theme.png");PostMessageW(manager.window,WM_CLOSE,0,0);check(WaitForSingleObject(manager.process.get(),20000)==WAIT_OBJECT_0,"shared-theme File Manager opens/renders/closes normally");manager.window=nullptr;
    }
    std::cout<<"PASS "<<checks<<" actual shipping "<<mode<<" import/retry/save/navigation checks\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<checks<<": "<<e.what()<<'\n';if(config.window){PostMessageW(config.window,WM_CLOSE,0,0);const auto until=GetTickCount64()+20000;while(WaitForSingleObject(config.process.get(),0)!=WAIT_OBJECT_0&&GetTickCount64()<until){if(const auto dialog=process_window(config.pid,L"#32770"))SendMessageW(dialog,TDM_CLICK_BUTTON,102,0);Sleep(20);}}if(manager.window){PostMessageW(manager.window,WM_CLOSE,0,0);WaitForSingleObject(manager.process.get(),20000);}try{close_panel(panel);}catch(...){}return 1;}}
